topics.example:
/* every paragraph */
p {
  color: navy;
}

/* only elements with class="notice" */
.notice {
  background-color: yellow;
}

body {
  font-family: Georgia, serif; /* serif is the backup */
  color: #2A1A20;
  background-color: #FFF8EF;
}

h1 {
  font-size: 40px;
  text-align: center;
}

* {
  box-sizing: border-box; /* width now includes padding and border */
}

.card {
  width: 300px;
  padding: 16px; /* space inside */
  border: 2px solid gray;
  margin: 24px; /* space outside */
}
